 */

#include "rmd_l_driver.h"
#include "../utils/logger.h"

RMD_L_Driver::RMD_L_Driver()
    : _initialized(false),
      _motorId(0),
      _currentPosition(0),
      _currentVelocity(0),
      _currentTorque(0),
      _targetPosition(0),
      _targetVelocity(0),
      _targetTorque(0),
      _enabled(false) {
    memset(&_config, 0, sizeof(RMD_L_Config));
    memset(&_status, 0, sizeof(RMD_L_Status));
}

RMD_L_Driver::~RMD_L_Driver() {
    deinit();
}

bool RMD_L_Driver::init(const RMD_L_Config& config) {
    _config = config;
    _motorId = config.motorId;

    // Initialize encoder
    if (!_encoder.init(config.encoderPinA, config.encoderPinB, config.encoderPinZ)) {
        Logger::error("RMD-L: Failed to initialize encoder");
        return false;
    }

    // Initialize motor driver
    if (!_motorDriver.init(config.motorPinPWM, config.motorPinDir)) {
        Logger::error("RMD-L: Failed to initialize motor driver");
        return false;
    }

    _initialized = true;
    _enabled = false;

    Logger::info("RMD-L: Driver initialized for motor ID " + String(_motorId));
    return true;
}

void RMD_L_Driver::deinit() {
    if (_initialized) {
        disable();
        _encoder.deinit();
        _motorDriver.deinit();
        _initialized = false;
        Logger::info("RMD-L: Driver deinitialized");
    }
}

bool RMD_L_Driver::enable() {
    if (!_initialized) {
        Logger::error("RMD-L: Driver not initialized");
        return false;
    }

    if (_enabled) {
        return true;
    }

    // Enable motor driver
    if (!_motorDriver.enable()) {
        Logger::error("RMD-L: Failed to enable motor driver");
        return false;
    }

    _enabled = true;
    Logger::info("RMD-L: Motor enabled");
    return true;
}

bool RMD_L_Driver::disable() {
    if (!_initialized || !_enabled) {
        return true;
    }

    // Disable motor driver
    if (!_motorDriver.disable()) {
        Logger::error("RMD-L: Failed to disable motor driver");
        return false;
    }

    _enabled = false;
    Logger::info("RMD-L: Motor disabled");
    return true;
}

bool RMD_L_Driver::isEnabled() const {
    return _enabled;
}

void RMD_L_Driver::setPosition(float position) {
    _targetPosition = position;
}

void RMD_L_Driver::setVelocity(float velocity) {
    _targetVelocity = velocity;
}

void RMD_L_Driver::setTorque(float torque) {
    _targetTorque = torque;
}

void RMD_L_Driver::stop() {
    _targetPosition = _currentPosition;
    _targetVelocity = 0;
    _targetTorque = 0;
}

void RMD_L_Driver::update() {
    if (!_initialized || !_enabled) {
        return;
    }

    // Read encoder
    _currentPosition = _encoder.getPosition();
    _currentVelocity = _encoder.getVelocity();

    // Update motor driver
    _motorDriver.update(_targetPosition, _targetVelocity, _targetTorque);

    // Update status
    _status.position = _currentPosition;
    _status.velocity = _currentVelocity;
    _status.torque = _motorDriver.getTorque();
    _status.errorCode = _motorDriver.getErrorCode();
}

RMD_L_Status RMD_L_Driver::getStatus() const {
    return _status;
}

RMD_L_Config RMD_L_Driver::getConfig() const {
    return _config;
}

uint8_t RMD_L_Driver::getMotorId() const {
    return _motorId;
}

bool RMD_L_Driver::isInitialized() const {
    return _initialized;
}
"}

