 * RMD-L Direct Drive Motor Driver - Header
 * 
 * Implements control interface for RMD-L direct drive motor series
 */

#ifndef RMD_L_DRIVER_H
#define RMD_L_DRIVER_H

#include <Arduino.h>
#include "motor_driver.h"

// RMD-L Configuration
typedef struct {
    uint8_t motorId;
    uint8_t encoderPinA;
    uint8_t encoderPinB;
    uint8_t encoderPinZ;
    uint8_t motorPinPWM;
    uint8_t motorPinDir;
    uint16_t encoderResolution;
    float maxVelocity;
    float maxTorque;
} RMD_L_Config;

// RMD-L Status
typedef struct {
    float position;
    float velocity;
    float torque;
    uint8_t errorCode;
    bool enabled;
} RMD_L_Status;

class RMD_L_Driver {
public:
    RMD_L_Driver();
    ~RMD_L_Driver();

    bool init(const RMD_L_Config& config);
    void deinit();

    bool enable();
    bool disable();
    bool isEnabled() const;

    void setPosition(float position);
    void setVelocity(float velocity);
    void setTorque(float torque);
    void stop();

    void update();
    RMD_L_Status getStatus() const;
    RMD_L_Config getConfig() const;
    uint8_t getMotorId() const;
    bool isInitialized() const;

private:
    bool _initialized;
    uint8_t _motorId;

    float _currentPosition;
    float _currentVelocity;
    float _currentTorque;

    float _targetPosition;
    float _targetVelocity;
    float _targetTorque;

    bool _enabled;

    RMD_L_Config _config;
    RMD_L_Status _status;

    Encoder _encoder;
    MotorDriver _motorDriver;
};

#endif // RMD_L_DRIVER_H
"}

